const test=require('node:test'),assert=require('node:assert/strict'),fs=require('fs'),vm=require('vm');
const ctx={console,TextEncoder,TextDecoder,btoa:s=>Buffer.from(s,'binary').toString('base64'),atob:s=>Buffer.from(s,'base64').toString('binary'),crypto:require('crypto').webcrypto};ctx.globalThis=ctx;ctx.window=ctx;vm.createContext(ctx);for(const f of ['data.js','core.js','planner.js'])vm.runInContext(fs.readFileSync('reda-2/'+f,'utf8'),ctx);const C=ctx.RedaCore,P=ctx.RedaPlanner;
test('same blueprint adapts approved variants to capacity',()=>{const low=P.assemble({blueprint:'chair',capacity:'supported',stage:'build'}),high=P.assemble({blueprint:'chair',capacity:'high',stage:'build'});assert.equal(low.items.find(i=>i.exercise==='chair').variant,'support');assert.equal(high.items.find(i=>i.exercise==='chair').variant,'free');assert.equal(high.items.find(i=>i.exercise==='calf').variant,'single');});
test('stage changes dose but never creates unknown exercise',()=>{const gentle=P.assemble({blueprint:'chair',capacity:'standard',stage:'gentle'}),loaded=P.assemble({blueprint:'chair',capacity:'standard',stage:'loaded'});assert.ok(gentle.items.every(i=>i.dose.sets<=2));assert.ok(loaded.items.some(i=>i.dose.sets>gentle.items.find(x=>x.exercise===i.exercise).dose.sets));loaded.items.forEach(i=>C.lookup(i.exercise,i.variant));});
test('floor constraint removes floor exercise',()=>{const p=P.assemble({blueprint:'hip',capacity:'supported',stage:'gentle',floor:false});assert.equal(p.items.some(i=>i.exercise==='bridge'),false);});
test('planner never enables automatic first-session progression',()=>{const p=P.assemble({blueprint:'chair',capacity:'high',stage:'loaded'});assert.equal(p.adjustment.enabled,false);assert.match(p.safety,/Ändra inte belastning eller svårighetsgrad/);});